class FadeCanvas final:public juce::Component {
public:
    Track::Region region;std::function<void(double,double)> edited;
    void paint(juce::Graphics& g)override{g.fillAll(juce::Colour(0xff111a24));if(region.length<=0)return;juce::Path curve;for(int n=0;n<=128;++n){const double time=region.length*n/128.0;const float x=float(n*getWidth()/128.0),y=12+(getHeight()-24)*(1-regionEnvelope(region,std::min(time,region.length-1e-12)));if(n==0)curve.startNewSubPath(x,y);else curve.lineTo(x,y);}g.setColour(juce::Colour(0xff55d8c2));g.strokePath(curve,juce::PathStrokeType(2));g.setColour(juce::Colours::white);g.fillEllipse(float(region.fadeIn/region.length*getWidth())-4,8,8,8);g.fillEllipse(float((1-region.fadeOut/region.length)*getWidth())-4,8,8,8);}
    void mouseDown(const juce::MouseEvent& e)override{left=e.x<getWidth()/2;mouseDrag(e);}
    void mouseDrag(const juce::MouseEvent& e)override{if(region.length<=0)return;const double amount=std::clamp(e.x/double(getWidth()),0.0,1.0);if(left)region.fadeIn=amount*region.length;else region.fadeOut=(1-amount)*region.length;repaint();}
    void mouseUp(const juce::MouseEvent&)override{if(edited)edited(region.fadeIn,region.fadeOut);}
private:bool left=true;
};
class AudioEditPanel final:public juce::Component,private juce::Timer {
public:
    AudioEditPanel(AudioRuntime& owner,EditModel& model,ApplyEdit edit,juce::File root,std::function<void()> notify):runtime(owner),engine(owner.engine),editor(model),apply(std::move(edit)),project(std::move(root)),changed(std::move(notify)){
        for(auto* c:std::initializer_list<juce::Component*>{&title,&curve,&fadeIn,&fadeOut,&inCurve,&outCurve,&fades,&crossLength,&crossShape,&cross,&slipTime,&slip,&ripple,&duplicate,&all,&undo,&redo,&stretch,&pitch,&cents,&process,&preview,&applyPreview,&revert,&cancel,&takes,&compStart,&compEnd,&compFade,&comp,&consolidate,&bounce,&status})addAndMakeVisible(c);
        for(auto* field:{&fadeIn,&fadeOut,&crossLength,&slipTime,&stretch,&pitch,&cents,&compStart,&compEnd,&compFade})field->setInputRestrictions(18,"0123456789.-");
        for(auto* box:{&inCurve,&outCurve,&crossShape}){box->addItemList({"Linear","Exponential","Equal-power"},1);box->setSelectedId(1,juce::dontSendNotification);}crossShape.setSelectedId(3,juce::dontSendNotification);
        fadeIn.setText("0");fadeOut.setText("0");crossLength.setText("0.02");slipTime.setText("0.1");stretch.setText("1");pitch.setText("0");cents.setText("0");compStart.setText(juce::String(editor.rangeStart,4));compEnd.setText(juce::String(editor.rangeEnd>editor.rangeStart?editor.rangeEnd:engine.duration(),4));compFade.setText("0.01");
        fades.onClick=[this]{action([&]{return editor.setFades(fadeIn.getText().getDoubleValue(),fadeOut.getText().getDoubleValue(),FadeCurve(inCurve.getSelectedId()-1),FadeCurve(outCurve.getSelectedId()-1));});};
        curve.edited=[this](double in,double out){fadeIn.setText(juce::String(in,6),false);fadeOut.setText(juce::String(out,6),false);fades.onClick();};
        cross.onClick=[this]{action([&]{return editor.crossfade(crossLength.getText().getDoubleValue(),FadeCurve(crossShape.getSelectedId()-1));});};
        slip.onClick=[this]{action([&]{return editor.slip(slipTime.getText().getDoubleValue());});};ripple.setClickingTogglesState(true);ripple.onClick=[this]{editor.ripple=ripple.getToggleState();};duplicate.onClick=[this]{action([&]{return editor.duplicate();});};all.onClick=[this]{editor.selectAll();changed();refresh();};undo.onClick=[this]{action([&]{return editor.undo();});};redo.onClick=[this]{action([&]{return editor.redo();});};
        process.onClick=[this]{startTransform(false);};preview.onClick=[this]{startTransform(true);};applyPreview.onClick=[this]{if(!resultClip)return;engine.stopPreview();juce::String error;const bool ok=apply([&]{editor.select(jobTrack,expected.id);return editor.adoptTransform(expected,resultClip,jobStretch,jobPitch,jobCents,error);});report(ok,error);};
        revert.onClick=[this]{action([&]{engine.stopPreview();return editor.revertOriginal();});};cancel.onClick=[this]{cancelled=true;engine.stopPreview();};
        comp.onClick=[this]{if(editor.selectedTrack<0)return;const auto& row=engine.track(editor.selectedTrack);const int index=takes.getSelectedId()-1;if(index<0||index>=int(row.takes.size()))return;const auto id=row.takes[index].id;juce::String error;report(apply([&]{return editor.comp(id,compStart.getText().getDoubleValue(),compEnd.getText().getDoubleValue(),compFade.getText().getDoubleValue(),error);}),error);};
        consolidate.onClick=[this]{startConsolidate();};bounce.onClick=[this]{startBounce();};applyPreview.setEnabled(false);refresh();setSize(840,710);startTimerHz(20);
    }
    ~AudioEditPanel()override{stopTimer();cancelled=true;if(worker.joinable())worker.join();offline.reset();engine.stopPreview();}
    void paint(juce::Graphics& g)override{g.fillAll(juce::Colour(0xff1b2532));g.setColour(juce::Colour(0xffc4d1df));g.setFont(13.0f);for(const auto& item:std::initializer_list<std::pair<juce::String,int>>{{"Fade In / Out (segundos) e curvas - arraste os pontos",58},{"Crossfade entre dois clips selecionados / Slip (segundos)",245},{"Duracao (fator) / Pitch (semitons) / Cents",340},{"Comp: take / Inicio / Fim / Crossfade (segundos)",470}})g.drawText(item.first,16,item.second,800,22,juce::Justification::centredLeft);}
    void resized()override{title.setBounds(16,14,808,34);curve.setBounds(16,84,808,108);fadeIn.setBounds(16,202,90,28);inCurve.setBounds(116,202,150,28);fadeOut.setBounds(284,202,90,28);outCurve.setBounds(384,202,150,28);fades.setBounds(550,202,140,28);
        crossLength.setBounds(16,274,90,28);crossShape.setBounds(116,274,150,28);cross.setBounds(284,274,140,28);slipTime.setBounds(450,274,90,28);slip.setBounds(550,274,140,28);
        ripple.setBounds(16,306,100,28);duplicate.setBounds(122,306,130,28);all.setBounds(266,306,145,28);undo.setBounds(430,306,100,28);redo.setBounds(540,306,100,28);
        stretch.setBounds(16,370,120,28);pitch.setBounds(150,370,120,28);cents.setBounds(284,370,120,28);process.setBounds(430,370,175,28);preview.setBounds(618,370,206,28);applyPreview.setBounds(16,410,205,30);revert.setBounds(235,410,205,30);cancel.setBounds(455,410,185,30);
        takes.setBounds(16,500,310,28);compStart.setBounds(340,500,95,28);compEnd.setBounds(449,500,95,28);compFade.setBounds(558,500,95,28);comp.setBounds(667,500,157,28);
        consolidate.setBounds(16,551,310,34);bounce.setBounds(340,551,310,34);status.setBounds(16,600,808,95);}
    int advanceValidation(){if(worker.joinable())return 0;if(validationStage==0){stretch.setText("1.25",false);pitch.setText("3",false);process.onClick();validationStage=1;return worker.joinable()?0:-1;}
        if(!jobSucceeded)return -1;if(validationStage==1){if(!editor.selected()||!editor.selected()->original||std::abs(editor.selected()->stretch-1.25)>1e-6)return -1;runtime.devices.removeAudioCallback(&engine);engine.startPreview(editor.selected()->asset);juce::AudioBuffer<float> output(2,64);engine.render(output.getArrayOfWritePointers(),2,64);const bool audible=output.getMagnitude(0,64)>0;engine.stopPreview();runtime.devices.addAudioCallback(&engine);if(!audible)return -1;consolidate.onClick();validationStage=2;return worker.joinable()?0:-1;}
        if(validationStage==2){bounce.onClick();validationStage=3;return worker.joinable()?0:-1;}if(validationStage==3)return jobFile.existsAsFile()&&editor.selected()&&!editor.selected()->original?1:-1;return -1;}
    void close(){cancelled=true;engine.stopPreview();}
    bool validateBindings(){auto* selected=editor.selected();if(!selected)return false;const auto id=selected->id;fadeIn.setText("0.05",false);fadeOut.setText("0.04",false);inCurve.setSelectedId(2,juce::dontSendNotification);fades.onClick();const bool shape=editor.selected()&&editor.selected()->fadeInCurve==FadeCurve::exponential;
        auto event=[this](float x){const auto now=juce::Time::getCurrentTime();return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),{x,12},juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier),1,0,0,0,0,&curve,&curve,now,{x,12},now,1,true);};curve.mouseDown(event(100));curve.mouseDrag(event(150));curve.mouseUp(event(150));const bool visual=editor.selected()&&editor.selected()->fadeIn>0.05;undo.onClick();const bool undone=editor.selected()&&std::abs(editor.selected()->fadeIn-0.05)<1e-6;
        duplicate.onClick();const bool duplicated=engine.track(editor.selectedTrack).regions.size()>=2;undo.onClick();editor.select(0,id);ripple.setToggleState(true,juce::dontSendNotification);ripple.onClick();const bool rip=editor.ripple;ripple.setToggleState(false,juce::dontSendNotification);ripple.onClick();refresh();return shape&&visual&&undone&&duplicated&&rip;}
private:
    AudioRuntime& runtime;AudioEngine& engine;EditModel& editor;ApplyEdit apply;juce::File project;std::function<void()> changed;
    juce::Label title,status;FadeCanvas curve;juce::TextEditor fadeIn,fadeOut,crossLength,slipTime,stretch,pitch,cents,compStart,compEnd,compFade;juce::ComboBox inCurve,outCurve,crossShape,takes;
    juce::TextButton fades{"Aplicar fades"},cross{"Crossfade"},slip{"Slip"},duplicate{"Duplicar"},all{"Selecionar todos"},undo{"Undo"},redo{"Redo"},process{"Aplicar duracao/pitch"},preview{"Pre-visualizar audio"},applyPreview{"Aplicar preview"},revert{"Reverter ao original"},cancel{"Cancelar / parar preview"},comp{"Comp trecho"},consolidate{"Consolidar clips selecionados"},bounce{"Bounce selecao (mix completo)"};juce::ToggleButton ripple{"Ripple"};
    std::thread worker;std::atomic<bool> cancelled{false},done{false};std::atomic<float> progress{0};juce::String jobError;std::shared_ptr<Clip> resultClip;std::unique_ptr<AudioEngine> offline;Track::Region expected;std::vector<Track::Region> jobRegions;int validationStage=0;uint64_t displayedId=0;int jobTrack=0,kind=0;bool previewOnly=false,jobSucceeded=false;double jobStretch=1,jobPitch=0,jobCents=0,jobStart=0,jobEnd=0;juce::File jobFile;
    void action(std::function<bool()> operation){report(apply(std::move(operation)),{});}
    void report(bool success,const juce::String& error){if(success){changed();status.setText("Edicao aplicada; fontes preservadas.",juce::dontSendNotification);}else status.setText(error.isEmpty()?"Selecione clips e valores validos para esta operacao.":error,juce::dontSendNotification);refresh();}
    bool begin(){if(worker.joinable()){status.setText("Processamento em andamento; aguarde ou cancele.",juce::dontSendNotification);return false;}if(engine.audioRecording||engine.midiRecording){status.setText("Pare a gravacao antes de processar audio.",juce::dontSendNotification);return false;}engine.stopPreview();cancelled=false;done=false;progress=0;jobError.clear();resultClip.reset();jobSucceeded=false;applyPreview.setEnabled(false);return true;}
    void startTransform(bool previewMode){auto* region=editor.selected();if(!region||!begin())return;expected=*region;jobTrack=editor.selectedTrack;jobStretch=stretch.getText().getDoubleValue();jobPitch=pitch.getText().getDoubleValue();jobCents=cents.getText().getDoubleValue();previewOnly=previewMode;kind=0;const auto cache=project.getChildFile(".nova-cache");
        worker=std::thread([this,cache]{try{resultClip=OfflineAudio::transform(expected,jobStretch,jobPitch,jobCents,cache,jobError,&cancelled,&progress);jobSucceeded=bool(resultClip);}catch(...){jobError="Falha no processamento offline; fontes preservadas.";}done.store(true,std::memory_order_release);});}
    bool range(bool selectedOnly){jobRegions.clear();jobStart=editor.rangeStart;jobEnd=editor.rangeEnd;jobTrack=editor.selectedTrack;if(jobEnd<=jobStart){jobStart=86400;jobEnd=0;for(int i=0;i<engine.trackCount();++i)for(const auto& r:engine.track(i).regions)if(editor.isSelected(r.id)){jobStart=std::min(jobStart,r.start);jobEnd=std::max(jobEnd,r.end());}}
        if(selectedOnly){if(jobTrack<0||jobTrack>=engine.trackCount())return false;for(int i=0;i<engine.trackCount();++i)for(const auto& r:engine.track(i).regions)if(editor.isSelected(r.id)){if(i!=jobTrack){status.setText("Consolide clips de uma faixa por vez.",juce::dontSendNotification);return false;}jobRegions.push_back(r);}}return jobStart>=0&&jobEnd>jobStart&&(!selectedOnly||!jobRegions.empty());}
    void startConsolidate(){if(!begin()||!range(true))return;kind=1;previewOnly=false;jobFile=project.getChildFile("Rendered").getChildFile("consolidated-"+juce::Uuid().toString()+".wav");const double rate=engine.sampleRate();worker=std::thread([this,rate]{try{resultClip=OfflineAudio::consolidate(jobRegions,jobStart,jobEnd,rate,jobFile,jobError,&cancelled,&progress);jobSucceeded=bool(resultClip);}catch(...){jobError="Falha ao consolidar; fontes preservadas.";}done.store(true,std::memory_order_release);});}
    void startBounce(){if(!begin()||!range(false))return;kind=2;previewOnly=false;{AudioEngine::MutationGuard guard(engine);offline=OfflineAudio::snapshot(engine,project.getChildFile(".nova-cache"),jobError);}if(!offline){status.setText(jobError,juce::dontSendNotification);return;}jobFile=project.getChildFile("Rendered").getChildFile("bounce-"+juce::Uuid().toString()+".wav");worker=std::thread([this]{try{jobSucceeded=OfflineAudio::bounce(*offline,jobStart,jobEnd,jobFile,jobError,&cancelled,&progress);}catch(...){jobError="Falha no bounce; fontes preservadas.";}done.store(true,std::memory_order_release);});}
    void finish(){worker.join();offline.reset();if(cancelled){status.setText("Processamento cancelado; fontes preservadas.",juce::dontSendNotification);resultClip.reset();return;}if(!jobSucceeded){status.setText(jobError,juce::dontSendNotification);return;}
        if(kind==2){status.setTooltip(jobFile.getFullPathName());status.setText("Bounce salvo em Rendered: "+jobFile.getFileName(),juce::dontSendNotification);return;}if(previewOnly){engine.startPreview(resultClip);applyPreview.setEnabled(true);status.setText("Preview pronto. Aplicar preview substitui o clip e permite Undo.",juce::dontSendNotification);return;}
        juce::String error;bool ok=false;ok=apply([&]{if(kind==0){editor.select(jobTrack,expected.id);return editor.adoptTransform(expected,resultClip,jobStretch,jobPitch,jobCents,error);}if(jobTrack>=engine.trackCount()){error="Faixa alterada durante consolidacao.";return false;}for(const auto& before:jobRegions){bool unchanged=false;for(const auto& current:engine.track(jobTrack).regions)if(current.id==before.id&&current.asset==before.asset&&current.start==before.start&&current.offset==before.offset&&current.length==before.length&&current.fadeIn==before.fadeIn&&current.fadeOut==before.fadeOut&&current.fadeInCurve==before.fadeInCurve&&current.fadeOutCurve==before.fadeOutCurve)unchanged=true;if(!unchanged){error="Clips alterados; arquivo renderizado preservado.";return false;}}editor.select(jobTrack,0);for(const auto& r:jobRegions){editor.selection.insert(r.id);if(!editor.selectedRegion)editor.selectedRegion=r.id;}return editor.adoptConsolidated(resultClip,jobStart,jobEnd,error);});report(ok,error);}
    void refresh(){title.setText("Audio: "+juce::String(editor.selection.size())+" clips selecionados",juce::dontSendNotification);if(auto* region=editor.selected()){curve.region=*region;curve.repaint();if(!fadeIn.hasKeyboardFocus(true))fadeIn.setText(juce::String(region->fadeIn,6),false);if(!fadeOut.hasKeyboardFocus(true))fadeOut.setText(juce::String(region->fadeOut,6),false);inCurve.setSelectedId(int(region->fadeInCurve)+1,juce::dontSendNotification);outCurve.setSelectedId(int(region->fadeOutCurve)+1,juce::dontSendNotification);if(!stretch.hasKeyboardFocus(true))stretch.setText(juce::String(region->stretch,3),false);if(!pitch.hasKeyboardFocus(true))pitch.setText(juce::String(region->semitones,3),false);if(!cents.hasKeyboardFocus(true))cents.setText(juce::String(region->cents,3),false);revert.setEnabled(bool(region->original));}undo.setEnabled(editor.canUndo());redo.setEnabled(editor.canRedo());ripple.setToggleState(editor.ripple,juce::dontSendNotification);
        displayedId=editor.selectedRegion;const int selected=takes.getSelectedId();takes.clear(juce::dontSendNotification);if(editor.selectedTrack>=0&&editor.selectedTrack<engine.trackCount())for(int n=0;n<int(engine.track(editor.selectedTrack).takes.size());++n)takes.addItem(engine.track(editor.selectedTrack).takes[n].file.getFileName()+" / take "+juce::String(n+1),n+1);if(takes.getNumItems())takes.setSelectedId(std::clamp(selected,1,takes.getNumItems()),juce::dontSendNotification);}
    void timerCallback()override{if(worker.joinable()){if(done.load(std::memory_order_acquire)){finish();refresh();}else status.setText("Processando audio: "+juce::String(progress.load()*100,1)+"%",juce::dontSendNotification);}else{if(displayedId!=editor.selectedRegion)refresh();title.setText("Audio: "+juce::String(editor.selection.size())+" clips selecionados",juce::dontSendNotification);if(auto* r=editor.selected()){curve.region=*r;curve.repaint();}}}
};
class AudioEditWindow final:public juce::DocumentWindow {
public:explicit AudioEditWindow(std::unique_ptr<AudioEditPanel> content):DocumentWindow("NOVA Audio Editor",juce::Colour(0xff1b2532),closeButton){setUsingNativeTitleBar(true);setContentOwned(content.release(),true);centreWithSize(840,710);setVisible(true);}
    void closeButtonPressed()override{if(auto* panel=dynamic_cast<AudioEditPanel*>(getContentComponent()))panel->close();setVisible(false);}
};
