std::unique_ptr<juce::DocumentWindow> createAdvancedAudioEditor(AudioRuntime& runtime,EditModel& editor,ApplyEdit apply,const juce::File& project,std::function<void()> changed){return std::make_unique<AudioEditWindow>(std::make_unique<AudioEditPanel>(runtime,editor,std::move(apply),project,std::move(changed)));}
int advanceAdvancedAudioEditorValidation(juce::DocumentWindow& window){if(auto* panel=dynamic_cast<AudioEditPanel*>(window.getContentComponent()))return panel->advanceValidation();return -1;}
bool validateAdvancedAudioEditorBindings(juce::DocumentWindow& window){if(auto* panel=dynamic_cast<AudioEditPanel*>(window.getContentComponent()))return panel->validateBindings();return false;}
